/* header.h: internal linkage, no ODR problem, compiler may inline */
static inline int clamp_add(int a, int b, int limit) {
    int s = a + b;
    return s > limit ? limit : s;         /* inlined: `limit` becomes a constant at each site */
}

/* C99 inline definition + one extern declaration to emit the external symbol */
/* a.c */  inline int shared_helper(int x) { return x * 2; }
/* b.c */  extern inline int shared_helper(int x);   // the only TU that emits it

/* force it (GCC/Clang): an always_inline that cannot be inlined is a compile error */
__attribute__((always_inline)) static inline int hot_clamp(int x) { return x < 0 ? 0 : x; }

/* MSVC */
__forceinline int hot_clamp_ms(int x) { return x < 0 ? 0 : x; }

